    """Estimate number of speakers using clustering."""
    if len(features) < 2:
        return 1

    distances = pdist(features, metric='cosine')
    Z = linkage(distances, method='average')

    # Estimate based on largest distance jumps in dendrogram
    n_merges = min(10, len(Z))
    last = Z[-n_merges:, 2]

    if len(last) > 1:
        last_diff = np.diff(last)
        if len(last_diff) > 0:
            idx_largest_jump = np.argmax(last_diff)
            n_speakers = min(n_merges - idx_largest_jump, max_speakers)
        else:
            n_speakers = min(len(features), max_speakers)
